require 'json';require 'fileutils';require 'open3';root=File.expand_path('..',__dir__);jdk=File.expand_path('../.toolchains/jdk-26.0.2.1.jdk/Contents/Home',root);handler=File.read(File.join(root,'server/GameSPI/src/main/java/com/aoo/bcg/gamespi/AuthoritativeSessionCommandHandler.java'));implementations=Dir[File.join(root,'server/{Mahjong,Poker}/src/main/java/**/*AuthoritativeSession.java')];stdout,stderr,status=Open3.capture3({'JAVA_HOME'=>jdk,'PATH'=>"#{jdk}/bin:#{ENV['PATH']}"},'./mvnw','-q','-pl','server/Mahjong,server/Poker','-am','-Dtest=MahjongAuthoritativeSessionTest,PokerAuthoritativeSessionTest,MahjongCoreEngineTest,PokerCoreEngineTest','-Dsurefire.failIfNoSpecifiedTests=false','test',chdir:root);checks={before_and_after:handler.include?('requireInvariants(session,"before")')&&handler.include?('requireInvariants(session,"after")'),all_authorities:implementations.all?{|path|File.read(path).include?('invariantViolations()')},mahjong_conservation:File.read(implementations.find{|p|p.include?('Mahjong')}).include?('TILE_CONSERVATION'),poker_ownership:File.read(implementations.find{|p|p.include?('Poker')}).include?('CARD_OWNERSHIP'),tests_passed:status.success?};result={task:'FSM08',passed:checks.values.all?,checks:checks,testStdout:stdout.strip,testStderr:stderr.strip};out=File.join(root,'work/audit/game-state-invariants.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(result)+"\n");puts JSON.generate(result);exit(result[:passed] ? 0 : 1)
